using System;using System.IO;using System.Linq;using System.Collections.Generic;
internal static class EventExpressionTests {
 static int checks;static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}static void Near(double a,double b,string message){Check(Math.Abs(a-b)<1e-10,message+": "+a+" != "+b);}
 static string[] fields={"eventCenterX","eventCenterY","eventOrbitSpeed","eventRadius","eventFriction"};
 static EditorState Scene(double cx,double cy,double omega,double radius,double friction){var source=new Track{id="source",name="source",kind="emitter",start=0,end=0,x=100,y=200,speed=0,count=1,life=100};var e=new Track{id="orbit",name="orbit",kind="control",start=2,end=2};EventPresets.ApplyPreset(e,"orbit-bullets");e.eventResetLife=false;e.eventRadiusMode="fixed";e.expressions=new Dictionary<string,string>{{"eventCenterX","global.cx+x/10"},{"eventCenterY","global.cy+source.y/10"},{"eventOrbitSpeed","global.omega+n/10+volley"},{"eventRadius","global.radius+point_distance(0,0,3,4)"},{"eventFriction","global.friction+speed/10"}};var s=new EditorState{fps=50,duration=10,randomSeed=103,tracks=new List<Track>{source,e}};string[] names={"cx","cy","omega","radius","friction"};double[] values={cx,cy,omega,radius,friction};for(int i=0;i<names.Length;i++)s.tracks.Add(new Track{id=names[i],kind="variable",variableName=names[i],variableDefault=values[i],variableExpression=values[i].ToString("R",System.Globalization.CultureInfo.InvariantCulture),start=0,end=0});Motion.Normalize(s);RandomParameters.Attach(s);return s;}
 public static void Main(string[] args){var reports=new List<object>();foreach(var numbers in new[]{new[]{100.0,200,.8,70,.2},new[]{-80.0,42,-1.25,120,.7}}){var original=Scene(numbers[0],numbers[1],numbers[2],numbers[3],numbers[4]);foreach(var s in new[]{original,Json.Read<EditorState>(Json.Write(original)),original.Snapshot()}){var world=new BulletWorld(s);world.Seek(1);var b=world.bullets.Single(v=>!v.dead);var e=s.tracks.Single(t=>t.id=="orbit");var values=new Dictionary<string,double>();foreach(var field in fields)values[field]=EventPresets.Value(e,field,b,world,2);Near(values[fields[0]],numbers[0]+10,"dynamic center X");Near(values[fields[1]],numbers[1]+20,"dynamic center Y");Near(values[fields[2]],numbers[2]+.1,"dynamic speed");Near(values[fields[3]],numbers[3]+5,"dynamic radius");Near(values[fields[4]],numbers[4],"dynamic friction");world.Seek(2);Near(b.orbitCenterX,values[fields[0]],"actual event captured X");Near(b.orbitCenterY,values[fields[1]],"actual event captured Y");Near(b.orbitSpeed,values[fields[2]],"actual event captured speed");Near(b.orbitRadius,values[fields[3]],"actual event fixed radius");world.Seek(0);world.Seek(2);Near(world.bullets.Single(v=>!v.dead).orbitCenterX,values[fields[0]],"reverse reconstruct");reports.Add(new{state=s,values=values});}}File.WriteAllText(args[0],Json.Write(new{checks=checks,rows=reports}));Console.WriteLine("PASS: "+checks+" existing event-expression C# checks (five fields, globals, JSON/snapshot, actual orbit and reverse).");}
}
